import 'trip_recorder.dart';
import 'trip_widgets.dart';
import 'trip_map.dart';

final TripRecorder _tripRecorder = TripRecorder();
GpsFix? _latestGpsFix;
TripSummary? _lastTripSummary;
Timer? _tripTimer;
double _boatCourse = 0;

bool _freshFix(GpsFix? fix, DateTime now) {
  if (fix == null) return false;
  return fix.latitude.isFinite && fix.longitude.isFinite &&
      fix.latitude >= -90 && fix.latitude <= 90 &&
      fix.longitude >= -180 && fix.longitude <= 180 &&
      fix.accuracyMetres.isFinite && fix.accuracyMetres >= 0 &&
      fix.accuracyMetres <= 50 &&
      now.difference(fix.timestamp) <= const Duration(seconds: 10) &&
      fix.timestamp.difference(now) <= const Duration(seconds: 2);
}

if (!_freshFix(fix, now)) {
  setState(() => _locationStatus = 'Waiting for an accurate GPS fix');
  return;
}
if (_trackingTrip) {
  if (!_tripRecorder.addFix(fix, now: now)) return;
} else if (_latestGpsFix != null &&
    !fix.timestamp.isAfter(_latestGpsFix!.timestamp)) {
  return;
}
final point = LatLng(fix.latitude, fix.longitude);
final course = _trackingTrip
    ? _tripRecorder.snapshot(now).gpsHeadingDegrees
    : ((fix.speedMetresPerSecond ?? 0) >= .5 &&
        (fix.speedAccuracyMetresPerSecond == null ||
            fix.speedAccuracyMetresPerSecond! <= 3) &&
        fix.courseDegrees != null && fix.courseDegrees!.isFinite &&
        fix.courseDegrees! >= 0 && fix.courseDegrees! < 360 &&
        (fix.courseAccuracyDegrees == null ||
            fix.courseAccuracyDegrees! <= 45)
        ? fix.courseDegrees : null);

if (course != null) _boatCourse = course;
_locationStatus = 'GPS accuracy ±${fix.accuracyMetres.toStringAsFixed(0)} m';
if (_trackingTrip) _advanceActiveLeg(point, fix.accuracyMetres);

unawaited(_mapController!.animateCamera(
  CameraUpdate.newLatLngZoom(point, 12),
  duration: const Duration(milliseconds: 450),
));

Future<Uint8List> _boatMarkerPng() async {
  final recorder = ui.PictureRecorder();
  final canvas = Canvas(recorder);
  final hull = Path()
    ..moveTo(32, 5)
    ..cubicTo(18, 17, 9, 38, 11, 65)
    ..lineTo(17, 86)
    ..quadraticBezierTo(32, 94, 47, 86)
    ..lineTo(53, 65)
    ..cubicTo(55, 38, 46, 17, 32, 5)
    ..close();
  canvas.drawShadow(hull, Colors.black, 4, true);
  canvas.drawPath(hull, Paint()..color = Colors.white);
  canvas.drawPath(hull, Paint()
    ..color = const Color(0xFF071B2C)
    ..style = PaintingStyle.stroke
    ..strokeWidth = 4);
  canvas.drawPath(Path()
    ..moveTo(32, 15)..lineTo(20, 42)..lineTo(44, 42)..close(),
    Paint()..color = const Color(0xFF25B8FF));
  canvas.drawRRect(
    RRect.fromRectAndRadius(const Rect.fromLTWH(20, 48, 24, 27),
        const Radius.circular(5)),
    Paint()..color = const Color(0xFF087D9D));
  canvas.drawLine(const Offset(22, 80), const Offset(42, 80),
      Paint()..color = const Color(0xFF071B2C)..strokeWidth = 3);
  final picture = recorder.endRecording();
  final image = await picture.toImage(64, 96);
  final png = await image.toByteData(format: ui.ImageByteFormat.png);
  image.dispose();
  picture.dispose();
  if (png == null) throw StateError('Could not create boat icon');
  return png.buffer.asUint8List();
}

