}

if (_plannedRoute.length < 2 || _trackingTrip) return;
final now = DateTime.now();
if (!_freshFix(_latestGpsFix, now)) {
  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
    content: Text('Waiting for a fresh, accurate GPS position before starting trip.'),
  ));

  _tripTimer?.cancel();
  _tripTimer = Timer.periodic(const Duration(seconds: 1), (_) {
    if (!mounted || !_trackingTrip) return;
    setState(() {
      if (!_freshFix(_tripRecorder.lastAcceptedFix, DateTime.now())) {
        _locationStatus = 'Waiting for fresh GPS • trip timer continues';
      }
    });
  });
  unawaited(_refreshMapData());
  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
    content: Text('Trip recording started.'),
    duration: Duration(seconds: 2),
  ));
}

